# 2) ego 차량 (RL 에이전트가 조종하는 빨간 차)
#    accel/decel은 SUMO 물리엔진이 허용하는 "한계치"이고,
#    실제 한 스텝에 얼마나 가감속할지는 mdp_config.py의
#    SPEED_DELTAS(행동 정의)가 결정한다.

EGO = {
    "accel": 5.4,          # 최대 가속도 (m/s^2)   /  행동 a=+1 일 때
    "decel": 5.4,          # 최대 감속도 (m/s^2)   /  행동 a=-1 일 때
    "max_speed": 22.22,    # 차량 자체의 최고속도 (= ROAD speed_limit)
    "depart_lane": "best", # 시작 차선. "best" = 경로상 가장 알맞은 차선 (SUMO가 고름)
                           #   "center" = 중앙 차선, 숫자 = 그 차선
    "depart_speed": 10,    # 시작 속도 (m/s)
    # True면 AV를 SUMO 기본 운전자가 운전한다 (정책 행동 무시, 신호·양보·경로 차선을 SUMO가 지킴).
    # 도로·교통 검증과 BC 전문가 데이터용. 학습·평가 때는 False.
    "sumo_driver": False,
    # SUMO 운전자 모드의 AV 차종 (반포 도로망, 수요 파일의 vType "ego_sumo" : 11/15 §12.0 4번).
    # 위 accel/decel 5.4는 RL 행동 a=±1의 한계치라 사람 운전자로 쓰면 지나치게 급하고, Krauss 기본 sigma 0.5는
    # 무작위로 멈칫거려 BC 시범 · 기준 지표가 흔들린다  /  SUMO 승용차 기본 가감속, 멈칫거림 없음.
    # 행동 칼럼(accel_raw)은 그대로 위 5.4로 정규화한다 (RL과 같은 행동 공간).
    "sumo_vtype": {"accel": 2.6, "decel": 4.5, "sigma": 0.0},
}


