# 버스 색 (화면용) : 서울시 버스 색상 체계(2004 개편): 간선 파랑 · 지선 초록 · 광역 빨강 · 순환 노랑.
# 경기 · 인천 직행좌석 · 광역급행(M)도 빨강. 유형은 노선 번호 규칙으로 판정 (11/14, 공식 노선 유형 자료 미보관 :
# 452는 OSM 서울 노선 목록 간선 확인, 0411 · 8641 지선은 팀 확인(11/14), 6020은 공항버스라 따로)
# 색은 실제 색 계열을 화면에서 잘 보이게 채도 · 밝기를 올린 값 (검은 차도 · 노랑 · 하늘 · 주황 · 분홍 승용차와 구분, 11/14)
BUS_COLORS = {"간선": "30,110,255", "지선": "0,210,60", "광역": "255,30,30", "순환": "255,200,0", "공항": "185,185,200"}
def _bus_type(line):
    if line.startswith("M") or line[:1] == "9" or (len(line) == 4 and line[0] in "56" and line != "6411" and line != "6020"):
        return "광역"          # M버스 · 9xxx 광역 · 경기 직행좌석(5104 오산 · 6427 · 6428 김포)
    if line == "6020":
        return "공항"          # 서울공항리무진
    if len(line) == 2:
        return "순환"
    if len(line) == 3:
        return "간선"          # 3자리 간선
    return "지선"              # 4자리 지선(0411 포함) · 8xxx 맞춤(지선형)


def _bus_lines(lines):
    """노선 표  /  road_builder가 읽는 dict. 출발 시각은 노선마다 배차간격 안에서 흩어 둔다
    (모두 0초에 출발하면 같은 입구에 버스 수십 대가 한꺼번에 몰린다). 황금비 수열이라 노선끼리 고르게 퍼진다."""
    out = []
    for i, (line, headway_min, path, stops) in enumerate(lines):
        period = headway_min * 60
        b = {"id": line, "period": period, "offset": round(((i * 0.6180339887) % 1.0) * period), "stops": list(stops),
             "color": BUS_COLORS[_bus_type(line)]}
        if isinstance(path, tuple):
            b["before_path"], b["after_path"] = path
        else:
            b["path"] = path
        out.append(b)
    return out



